 a,z=xrange;c,d=yrange
 def xy(t,v):return(65+470*(t-a)/(z-a),325-250*(v-c)/(d-c))
 def path(ps):return' '.join(f'{xy(t,v)[0]:.2f},{xy(t,v)[1]:.2f}'for t,v in ps)
